INSERT INTO about (image, title, description, seo_description, seo_title, language)
SELECT image, 'من هو MSc. Dt. Mehmet Taş؟',
'<p>وُلد طبيب الأسنان Mehmet Taş عام 1986 في إلبستان بولاية كهرمان مرعش. وأتمّ دراسته الابتدائية والمتوسطة والثانوية في مرسين. والتحق عام 2004 بكلية طب الأسنان في جامعة إسطنبول وتخرّج منها عام 2009. وأدّى الخدمة العسكرية عام 2010 في توكات برتبة ملازم احتياط.</p>
<p>وبعد تخرّجه عمل نحو عامين طبيب أسنان في مستشفى Tem الخاص. وهو من الشركاء المؤسسين لعيادة Denttek الخاصة لصحة الفم والأسنان العاملة منذ عام 2012. وفي عام 2020 أكمل دراسة الماجستير في قسم جراحة الفم وزراعة الأسنان بجامعة UniCamillus في إيطاليا.</p>
<p>وهو عضو في جمعية أكاديمية طب الأسنان التجميلي وفي جمعية OSSEDER. ويعمل بشكل رئيسي في مجالات جراحة الزراعة وطب الأسنان التجميلي وتصميم الابتسامة وتطبيقات البوتوكس في العضلة الماضغة. ويتقن الإنجليزية. ويهتم بالتصوير السنّي؛ وهو متزوج وأب لطفل.</p>
<h2>التعليم والمسيرة المهنية</h2>
<table>
<thead><tr><th>السنة</th><th>المرحلة</th></tr></thead>
<tbody>
<tr><td>2004–2009</td><td>كلية طب الأسنان بجامعة إسطنبول — الدراسة الجامعية والتخرّج</td></tr>
<tr><td>2010</td><td>الخدمة العسكرية (توكات، ملازم احتياط)</td></tr>
<tr><td>2010–2012</td><td>مستشفى Tem الخاص — طبيب أسنان</td></tr>
<tr><td>2012</td><td>عيادة Denttek الخاصة لصحة الفم والأسنان — شريك مؤسس</td></tr>
<tr><td>2020</td><td>جامعة UniCamillus (إيطاليا) — ماجستير جراحة الفم وزراعة الأسنان</td></tr>
</tbody>
</table>
<h2>العضويات المهنية ومجالات الاهتمام</h2>
<ul>
<li>عضوية جمعية أكاديمية طب الأسنان التجميلي</li>
<li>عضوية OSSEDER (جمعية الاندماج العظمي)</li>
<li>جراحة الزراعة والتخطيط الجراحي المتقدّم</li>
<li>طب الأسنان التجميلي وتصميم الابتسامة</li>
<li>بوتوكس العضلة الماضغة — تطبيقات عضلة المضغ المرتبطة بشدّ الأسنان وصريرها</li>
<li>التصوير السنّي وتوثيق الحالات</li>
</ul>
<h2>النهج السريري</h2>
<p>في طب الأسنان لا يوجد حل واحد صحيح للجميع. فقد تختلف الخطة لدى شخصين يأتيان بالشكوى ذاتها؛ لأن أنسجة السن السليمة المتبقية ودعم اللثة والعظم وعلاقة الإطباق والحالة الصحية العامة وعادات العناية اليومية تختلف من شخص لآخر.</p>
<p>لذلك يُتَّخذ قرار العلاج بتقييم الاستماع إلى الشكوى والتاريخ الطبي والسني والفحص السريري والتصوير الذي يُرى ضروريًا فقط، معًا. ويُناقَش بوضوح هدف كل خيار قابل للتطبيق وفوائده ومخاطره المهمة وبدائله والنتائج المحتملة لعدم العلاج. والموافقة المستنيرة ليست مجرد توقيع؛ بل مسار إعلام مفهوم وإتاحة لطرح الأسئلة.</p>
<p>وفي العلاجات الشاملة تُقسَّم الإجراءات إلى مراحل: أولًا ضبط الحالة الطارئة والعدوى، ثم إيقاف المرض وصحة اللثة الأساسية، ثم المراحل الترميمية أو الجراحية أو التعويضية النهائية، وأخيرًا نظام العناية والمراجعة. وللتفاصيل يمكنك مراجعة صفحة <a href="/ar/tedavi-plani-ve-surec/">خطة العلاج ومساره</a>، ولمعرفة ما يُقيَّم في الفحص الأول صفحة <a href="/ar/ilk-dis-muayenesi-tedavi-planlamasi/">الفحص الأول للأسنان وتخطيط العلاج</a>.</p>
<h2>كادرنا الطبي</h2>
<p>يعمل في عيادتنا أطباء في مجالات زراعة الأسنان وجراحة الفم وعلاج الجذور وطب أسنان الأطفال والتقويم والعلاج الترميمي والتعويضات. وتُطبَّق العلاجات كافة في مجال طب الأسنان داخل عيادتنا. ولمعرفة كادرنا الطبي بالكامل: <a href="https://denttek.com.tr/hekimlerimiz/" target="_blank" rel="noopener">Özel Denttek — أطباؤنا</a></p>
<h2>الأسئلة الشائعة</h2>
<p><strong>في أي المجالات يعمل MSc. Dt. Mehmet Taş؟</strong><br>يعمل بشكل رئيسي في مجالات جراحة الزراعة وجراحة الفم وطب الأسنان التجميلي. أما الإجراءات في مجالات علاج الجذور وطب أسنان الأطفال والتقويم والعلاج الترميمي والتعويضات فتُنفَّذ مع الأطباء المعنيين في العيادة.</p>
<p><strong>في أي مجال درجة الماجستير؟</strong><br>أُنجزت في جامعة UniCamillus بإيطاليا في مجال جراحة الفم وزراعة الأسنان (2020).</p>
<p><strong>هل بوتوكس العضلة الماضغة ضمن نطاق طب الأسنان؟</strong><br>نعم. فلدى من تُفرط عضلة المضغ لديهم في العمل وتتضخم بسبب شدّ الأسنان وصريرها (البروكسيزم)، يكون تطبيق ذيفان البوتولينوم خيارًا علاجيًا موجّهًا لمنطقة الفك والوجه. ويُتَّخذ القرار بتناول تقييم الإطباق وفحص العضلات والمفصل ونتائج التآكل معًا، ويُقيَّم غالبًا مع خيارات مثل الجبير الليلي.</p>
<p><strong>هل يمكنني المراجعة لأخذ رأي ثانٍ؟</strong><br>نعم. فأخذ رأي ثانٍ حق للمريض. وإحضار صورك الشعاعية وتقاريرك وسجلات علاجك الحالية يسهّل التقييم.</p>
<p><strong>هل يمكن إجراء المقابلة بالإنجليزية؟</strong><br>نعم، فالطبيب يتقن الإنجليزية.</p>
<p><strong>كيف تُحفَظ سجلات علاجي؟</strong><br>المعلومات التي يُحصل عليها في مسارات الفحص والتصوير والعلاج بيانات شخصية ذات طبيعة خاصة. ويُشرح في <a href="/ar/sayfa/kvkk-aydinlatma-metni">إشعار حماية البيانات الشخصية</a> لأي غرض تُعالَج وما الحقوق التي تملكها.</p>
<h2>تقييم محلي</h2>
<p>في عيادتنا الواقعة على تخوم بيليكدوزو/إسنيورت تُوضع خطة العلاج بتقييم الفحص السريري والتصوير اللازم وتوقعات المريض معًا وتُشارَك معه.</p>
<p><a href="/ar/tedaviler">عناوين العلاج</a> &middot; <a href="/ar/implant/">علاج الزراعة</a> &middot; <a href="/ar/estetik/">طب الأسنان التجميلي</a> &middot; <a href="/ar/iletisim">الموعد والتواصل</a></p>',
'تعرّف على تعليم الدكتور Mehmet Taş ومسار الماجستير في جراحة الفم وزراعة الأسنان وخبرته السريرية ونهجه العلاجي.',
'من هو MSc. Dt. Mehmet Taş؟ | التعليم والنهج السريري',
'AR' FROM about WHERE language = 'TR';

INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'إشعار حماية البيانات الشخصية',
'<p>أُعِدّ هذا الإشعار من قبل Dt. Mehmet Taş بصفته المسؤول عن البيانات وفقًا للقانون التركي رقم 6698 بشأن حماية البيانات الشخصية («KVKK»)، ويتعلق بمعالجة البيانات الشخصية للزوار الذين يستخدمون نموذج التواصل وحجز الموعد على موقع dtmehmettas.com.tr.</p>
<h2>المسؤول عن البيانات</h2>
<p>Dt. Mehmet Taş — Cumhuriyet Mah. Nazım Hikmet Blv. No: 89/2, Esenyurt / İstanbul. البريد الإلكتروني: info@dtmehmettas.com.tr، الهاتف: +90 543 558 85 19.</p>
<h2>البيانات الشخصية التي تُعالَج</h2>
<p>عبر نموذج التواصل نعالج اسمك ولقبك ورقم هاتفك وعنوان بريدك الإلكتروني (اختياري) والمعلومات التي تكتبها في حقل الرسالة فقط. ولا تُطلب عبر هذا النموذج بيانات صحية أو تشخيصات أو معلومات علاجية؛ ولا ننصح بكتابة مثل هذه المعلومات في حقل الرسالة.</p>
<h2>أغراض المعالجة</h2>
<p>تُعالَج بياناتك الشخصية للأغراض التالية: تلقّي طلبات التواصل والمواعيد، والرد على استفسارك، والإعلام بشأن تنظيم الموعد، والاحتفاظ بسجل للطلبات. ولا تُستخدم بياناتك لأغراض إعلانية أو تسويقية ولا تُشارَك مع أطراف ثالثة لأغراض تجارية.</p>
<h2>الأساس القانوني وطريقة الجمع</h2>
<p>تُجمع بياناتك إلكترونيًا عبر النموذج الموجود على الموقع وتُعالَج استنادًا إلى الأسس القانونية المذكورة في المادة 5 من قانون KVKK، وهي أن المعالجة «ترتبط مباشرةً بإبرام عقد أو تنفيذه» وأنها «لازمة للمصالح المشروعة للمسؤول عن البيانات بشرط عدم المساس بالحقوق والحريات الأساسية لصاحب البيانات».</p>
<h2>النقل والمشاركة</h2>
<p>تُحفَظ بيانات النموذج لدى مزوّد خدمة الاستضافة الذي يعمل عليه الموقع. ولا تُنقل إلى أطراف ثالثة داخل البلاد أو خارجها دون التزام قانوني.</p>
<h2>مدة الحفظ</h2>
<p>تُحفَظ بيانات طلب التواصل مدة أقصاها سنة واحدة بعد انتهاء الطلب ثم تُحذف أو تُجهَّل. وإذا تحوّل الطلب إلى ملف مريض فتُطبَّق مدد الحفظ المنصوص عليها في تشريعات الصحة.</p>
<h2>حقوقك بصفتك صاحب البيانات</h2>
<p>وفقًا للمادة 11 من قانون KVKK يحق لك: معرفة ما إذا كانت بياناتك الشخصية تُعالَج؛ وطلب معلومات إن كانت قد عُولجت؛ ومعرفة غرض المعالجة وما إذا كانت تُستخدم وفق الغرض؛ ومعرفة الأطراف الثالثة التي نُقلت إليها؛ وطلب التصحيح عند المعالجة الناقصة أو الخاطئة؛ وطلب الحذف أو الإتلاف؛ وطلب إبلاغ الأطراف الثالثة التي نُقلت إليها البيانات بهذه الإجراءات؛ والاعتراض على نتيجة تكون في غير صالحك ناشئة حصرًا عن تحليل آلي؛ وطلب التعويض إذا لحقك ضرر من معالجة غير مشروعة. ويمكنك توجيه طلباتك كتابةً إلى بيانات التواصل المذكورة أعلاه؛ وسيُرَدّ عليها خلال 30 يومًا كحد أقصى.</p>
<p><em>هذا النص العربي للإعلام. وعند وجود اختلاف تكون النسخة التركية من هذا الإشعار هي المعتمدة.</em></p>
<p><em>آخر تحديث: 21.09.2026</em></p>',
'إشعار حماية البيانات الشخصية المتعلقة بالبيانات التي تُجمع عبر نموذج التواصل وحجز الموعد على موقع dtmehmettas.com.tr.',
'إشعار حماية البيانات الشخصية | MSc. Dt. Mehmet Taş',
'AR' FROM pages WHERE link = 'kvkk-aydinlatma-metni';
